}

int counter = 0;

int next() {
  counter++;
  return counter;
}

class Box {
  late final int value = next();
}

void main() {
  final box = Box();
  print(counter);
  print(box.value);
  print(box.value);
  print(counter);
}

import 'dart:async';

void main() {
  print('1');
  Future(() => print('2'));
  scheduleMicrotask(() => print('3'));
  Future.value(4).then(print);
  Future.microtask(() => print('5'));
  print('6');
}

Stream<int> inner() async* {
  print('inner');
  yield 2;
}

Stream<int> outer() async* {
  print('outer');
  yield 1;
  yield* inner();
}

void main() {
  final stream = outer();
  print('created');
  stream.listen(print);
  print('listened');
}

