  controller.stream.listen(print);
  controller.stream.listen(print);
  controller.add(1);
}

sealed class Shape {}

class Circle extends Shape {
  final double r;
  Circle(this.r);
}

class Square extends Shape {
  final double side;
  Square(this.side);
}

double area(Shape shape) => switch (shape) {
  Circle(:final r) => 3.14 * r * r,
  Square(:final side) => side * side,
};

class Point {
  final int x;
  const Point(this.x);
}

void main() {
  print(identical(const Point(1), const Point(1)));
  print(identical(Point(1), Point(1)));
  print(const [1] == const [1]);
  print([1] == [1]);
}

class A {
  String name() => 'A';
}

mixin B on A {
  @override
  String name() => 'B>${super.name()}';
}

mixin C on A {
  @override
  String name() => 'C>${super.name()}';
}

class D extends A with B, C {}

void main() {
  print(D().name());
}

